add_cart_item.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;
import static java.util.Map.entry;

Map<String, String> address = Map.ofEntries(entry("first_name", "Alex"), entry("last_name", "Taylor"),
        entry("address_line1", "1 Example Street"), entry("address_line2", ""), entry("city", "Sydney"),
        entry("post_code", "2000"), entry("phone", ""), entry("mobile", ""), entry("fax", ""),
        entry("email", "alex.taylor@example.com"), entry("country_code", "AU"), entry("state_code", "NSW"));
ApiResponse response = client.carts().addCartItem(Map.of("product_id", 101, "quantity", 1, "customer_id", 45,
        "session_id", "cart-7f3a9c2e1b", "shipping_address", address));
Map<?, ?> cart = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("cart");
Map<?, ?> item = (Map<?, ?>) ((List<?>) cart.get("items")).get(0);
System.out.println(cart.get("session_id") + " " + cart.get("customer_id") + " " + item.get("id"));
System.out.println(item.get("quantity") + " " + ((Map<?, ?>) cart.get("shipping")).get("shipping_tax"));

get_cart.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.carts().getCart("cart-7f3a9c2e1b");
Map<?, ?> cart = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("cart");
for (Object row : (List<?>) cart.get("items")) {
    Map<?, ?> item = (Map<?, ?>) row;
    Map<?, ?> product = (Map<?, ?>) item.get("product");
    System.out.println(item.get("id") + " " + product.get("name") + " " + item.get("quantity"));
}
Map<?, ?> totals = (Map<?, ?>) cart.get("totals");
System.out.println(totals.get("subtotal") + " " + ((Map<?, ?>) cart.get("shipping")).get("shipping_tax")
        + " " + totals.get("grand_total"));

